def rle(s):
    if not s: return ""

    result = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    # Append the last character and its count
    result.append(f"{current_char}{count}")

    return "".join(result)

def balanced(s):
    stack = []

    # Mapping of closing to opening brackets
    pairs = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()

    # If the stack is empty, all brackets were balanced
    return len(stack) == 0

def to_base(n, b):
    if not isinstance(b, int) or b < 2:
        raise ValueError("Base must be an integer >= 2")

    # Handle zero explicitly as per requirement "Zero is '0'"
    if n == 0:
        return "0"

    digits = []
    while n > 0:
        remainder = n % b
        digit_char = str(remainder) if remainder < 10 else chr(ord('a') + remainder - 10)
        digits.append(digit_char)
        n //= b

    # The remainders are generated in reverse order (least significant first), so we must reverse the list.
    return "".join(digits[::-1])
